<script setup lang="ts">import type{DashboardAlert}from '@/types/dashboard';defineProps<{items:DashboardAlert[];loading:boolean}>();const emit=defineEmits<{handle:[path:string]}>();const meta={info:{color:'info',icon:'mdi-information-outline',label:'Thông tin'},warning:{color:'warning',icon:'mdi-alert-outline',label:'Cảnh báo'},critical:{color:'error',icon:'mdi-alert-octagon-outline',label:'Nghiêm trọng'}} as const</script>
<template><v-card class="pa-4 pa-md-5 h-100" border rounded="xl"><div class="d-flex justify-space-between mb-4"><div><div class="text-h6 font-weight-bold">Cần xử lý</div><div class="text-caption text-medium-emphasis">Các vấn đề cần chú ý ngay</div></div><v-badge :content="items.length" color="error"><v-icon icon="mdi-bell-alert-outline" size="26"/></v-badge></div><v-skeleton-loader v-if="loading" type="list-item-avatar-two-line@4"/><div v-else-if="!items.length" class="empty-state"><v-icon icon="mdi-check-decagram-outline" color="success" size="44"/><div>Không có cảnh báo</div></div><div v-else><div v-for="item in items" :key="item.key" class="alert-row"><v-avatar :color="meta[item.severity].color" variant="tonal" size="38"><v-icon :icon="meta[item.severity].icon"/></v-avatar><div class="flex-grow-1"><div class="font-weight-medium">{{ item.title }}</div><div class="text-caption" :class="`text-${meta[item.severity].color}`">{{ item.count }} trường hợp · {{ meta[item.severity].label }}</div></div><v-btn size="small" variant="text" color="primary" @click="emit('handle',item.path)">Xử lý</v-btn></div></div></v-card></template>
